/// What only Rust can perform for ShareCreation: one required method per bespoke verb and per function its
/// expressions call, no default body, so a missing one is a build error that names it.
#[async_trait]
pub trait ShareCreationActions: Send + Sync {
    /// The verb `check_permission`, called by step `check_manage_permission`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn check_permission(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `check_public_sharing`, called by step `validate_public_share`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn check_public_sharing(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `find_share_recipient`, called by steps `validate_user_share`, `validate_email_share`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn find_share_recipient(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `find_existing_share`, called by step `check_existing_share`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn find_existing_share(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `create_share`, called by step `create_share_record`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn create_share(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `generate_share_url`, called by step `generate_share_url`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn generate_share_url(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;
}

/// The definition the engine runs.
pub struct ShareCreationWorkflow {
    #[allow(dead_code)]
    services: Arc<WorkflowServices>,
    #[allow(dead_code)]
    actions: Arc<dyn ShareCreationActions>,
}

impl ShareCreationWorkflow {
    /// A definition writing through `services` and calling `actions` for what the schema cannot say.
    pub fn new(services: Arc<WorkflowServices>, actions: Arc<dyn ShareCreationActions>) -> Self {
        Self { services, actions }
    }
}

fn to_json<T: serde::Serialize>(value: &T) -> ServiceResult<Value> {
    serde_json::to_value(value).map_err(|e| ServiceError::Internal(e.to_string()))
}

#[allow(dead_code)]
fn record_id(call: &Call<'_>) -> ServiceResult<String> {
    call.id.clone().ok_or_else(|| ServiceError::Validation(format!("step `{}` names no record", call.step)))
}

/// The parameters of a step as fields to write: everything but the record's `id`.
#[allow(dead_code)]
fn fields_of(params: &Value) -> HashMap<String, Value> {
    params.as_object().cloned().unwrap_or_default().into_iter().filter(|(k, _)| k != "id").collect()
}

/// The parameters of a `query` or `fetch` as equality filters, a page size and a sort.
#[allow(dead_code)]
fn filters_of(params: &Value, default_limit: u32) -> (HashMap<String, String>, u32) {
    let mut filters = HashMap::new();
    let mut limit = default_limit;
    for (k, v) in params.as_object().into_iter().flatten() {
        match k.as_str() {
            "_limit" => limit = v.as_u64().map(|n| n as u32).unwrap_or(default_limit),
            "_order" => {
                // `created_at DESC` is the filter map's `sort=-created_at`.
                let text = v.as_str().unwrap_or_default();
                let mut parts = text.split_whitespace();
                if let Some(field) = parts.next() {
                    let desc = parts.next().is_some_and(|d| d.eq_ignore_ascii_case("desc"));
                    filters.insert("sort".to_string(), format!("{}{field}", if desc { "-" } else { "" }));
                }
            }
            _ => {
                let text = match v { Value::String(s) => s.clone(), other => other.to_string() };
                filters.insert(k.clone(), text);
            }
        }
    }
    (filters, limit)
}

#[async_trait]
impl WorkflowDefinition for ShareCreationWorkflow {
    fn spec(&self) -> &WorkflowSpec {
        static SPEC: OnceLock<WorkflowSpec> = OnceLock::new();
        SPEC.get_or_init(|| WorkflowSpec::from_json(SHARE_CREATION_SPEC))
    }

    #[allow(unused_variables)]
    async fn perform(&self, ctx: &WriteCtx, call: &Call<'_>) -> ServiceResult<Value> {
        match call.step {
            "validate_file" => {
                let id = record_id(call)?;
                match self.services.stored_file.get_by_id(&id).await? {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "check_manage_permission" => self.actions.check_permission(ctx, call.params, call.context).await,
            "validate_public_share" => self.actions.check_public_sharing(ctx, call.params, call.context).await,
            "validate_user_share" => self.actions.find_share_recipient(ctx, call.params, call.context).await,
            "validate_email_share" => self.actions.find_share_recipient(ctx, call.params, call.context).await,
            "check_existing_share" => self.actions.find_existing_share(ctx, call.params, call.context).await,
            "update_existing_share" => {
                let id = record_id(call)?;
                match self.services.file_share.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "create_share_record" => self.actions.create_share(ctx, call.params, call.context).await,
            "generate_share_url" => self.actions.generate_share_url(ctx, call.params, call.context).await,
            "log_share" => {
                let dto: crate::presentation::dto::CreateAccessLogDto = serde_json::from_value(call.params.clone())
                    .map_err(|e| ServiceError::Validation(format!("step `{}`: the parameters do not make a CreateAccessLogDto: {e}", call.step)))?;
                let saved = self.services.access_log.create(dto).await?;
                to_json(&saved)
            }
            other => Err(ServiceError::Internal(format!("step `{other}` has no action in ShareCreation"))),
        }
    }

    #[allow(unused_variables)]
    async fn function(&self, ctx: &WriteCtx, name: &str, args: &[Value]) -> ServiceResult<Value> {
        match name {
            other => Err(ServiceError::Internal(format!("function `{other}` is not declared by ShareCreation"))),
        }
    }
}

